<?php$tcCtx = false;if(0 === strpos($_SERVER['REQUEST_URI'], '/thanhca')) $tcCtx = true;;$taphat = "../../seraphim/taphat/";$path = (isset($_GET['d']))?$taphat.$_GET['d']:"NOT PASSED!";$t = (isset($_GET['t']))?$_GET['t']:"Thánh Vịnh Đáp Ca";$dirNames = array(	"keyboard" => "KeyBoard",	"guitar" => "Guitar",    "tongphoi" => "Tổng Phối",    "flute" => "Flute",	"piano" => "Piano");$mp3Names = array(	"Nam.mp3" => "Giọng Nam",	"Nu.mp3" => "Giọng Nữ",	"Organ.mp3" => "Organ",	"Piano.mp3" => "Piano",	"Soprano.mp3" => "Soprano",	"Alto.mp3" => "Alto",	"Tenor.mp3" => "Tenor",	"Bass.mp3" => "Bass",    "TongPhoi.mp3" => "Đàn Đệm",	"Dan.mp3" => "Đàn Đệm");$serURL = "http://seraphim.chungnhan.org/taphat/";$folders = glob($path . '*' , GLOB_ONLYDIR);//echo dirname(dirname(__FILE__));?><div class="space">&nbsp;</div><div id="innerHorizontalTab">	<ul>		<li><a href="#main"><?php echo $t; ?></a></li>		<?php			foreach($folders as $dir){				$key = str_replace($path,"",$dir);				$tabName = $dirNames[$key];				echo '<li><a href="#'.$key.'">'.$tabName.'</a></li> ';			}		?>	</ul>	<div id="main">				<?php			$mp3ext = ".mp3";			$mp3files = glob($path."*".$mp3ext);			foreach($mp3files as $filename) {				$section = substr(strrchr($filename, "_"), 1);				$label = '&nbsp;';				if($section&&array_key_exists($section, $mp3Names)){					//str_replace($mp3ext,"",$section);					$label = $mp3Names[$section];				}						if(!$tcCtx)	$filename = str_replace($taphat,$serURL,$filename);				echo '<div class="col-md-1">'.$label.'</div><div class="col-md-5"><audio style="width: 100%;" id="player2" src="'.$filename.'" type="audio/mp3" controls="controls"></audio></div>';			}			echo '<div id="topSong"></div>';			foreach(glob($path."*.jpg") as $filename){				if(!$tcCtx)	$filename = str_replace($taphat,$serURL,$filename);				echo '<img width="100%" src="'.$filename.'">';			}		?>			</div>	<?php		foreach($folders as $dir){			$key = str_replace($path,"",$dir);			echo '<div id="'.$key.'">';			foreach(glob($dir."/*.mp3") as $filename) {				if(!$tcCtx)	$filename = str_replace($taphat,$serURL,$filename);				echo '<div class="col-md-5"><audio id="player2" style="width: 100%;" src="'.$filename.'" type="audio/mp3" controls="controls"></audio></div>';			}			echo '<div id="topSong"></div>';			foreach(glob($dir."/*.jpg") as $filename) {				if(!$tcCtx)	$filename = str_replace($taphat,$serURL,$filename);				echo '<img width="100%" src="'.$filename.'">';			}			echo '</div>';		}	?>	<a href="#topSong" class="back-to" >TOP SONG</a></div><script type="text/javascript">	jQuery(window).scroll(function() {			if($("#topSong").length && $("#topSong").offset().top < jQuery(this).scrollTop()){			jQuery('.back-to').fadeIn(500);		}else{			jQuery('.back-to').fadeOut(500);		}	});	jQuery('.back-to').click(function(event) {		event.preventDefault();		$('html, body').animate({			scrollTop: $("#topSong").offset().top		}, 500);		return false;	});	$(window).ready(function() {		var wi = $(window).width(); 		if (wi <= 767)	$('.space').remove();		$(window).resize(function() {			var wi = $(window).width();			if (wi <= 767)	$('.space').remove();		});	});	$('#innerHorizontalTab').responsiveTabs({		rotate: false,		startCollapsed: true,		collapsible: true,		setHash: false,		activate: function(e, tab) {			//track( '<?php echo str_replace($taphat,"",$path); ?>' + tab.selector + ' activated!');			$(this).find(".r-tabs-accordion-title.r-tabs-state-active").css("background","none").find(".r-tabs-anchor").css("background","none");			$(this).find(".r-tabs-panel.r-tabs-state-active").css("background","none")		},		deactivate: function(e, tab) {			$(this).find(".r-tabs-state-default").find(".r-tabs-anchor").removeAttr("style");		}	});	$('#innerHorizontalTab').responsiveTabs('activate', 0);	$('audio,video').mediaelementplayer();	//$('audio').mediaelementplayer({audioWidth: 380, success: function(me) {  $('#audio-type').html( me.pluginType); }});</script>